-- Passage wg7-paragraph-transitions-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b29390a6-cef7-55b0-b93f-e32aff1127e5', 'wg7-paragraph-transitions-p05', (select id from public.skills where slug = 'write-g7-paragraph-transitions'), null,
        '6-8', $q$The Journey of a Snowflake$q$, $q$(1) Every snowflake begins high in a cloud as a tiny speck of dust or pollen. (2) When the air is below freezing, water vapor sticks to the speck and freezes into a small ice crystal. (3) The crystal has six sides because of the way water molecules fit together as they freeze. (4) As the crystal falls through the cloud, more water vapor freezes onto its six corners. (5) ____, these corners grow into the long, lacy arms that people notice on snowflakes.

(6) No two snowflakes take exactly the same path to the ground. (7) Each one passes through pockets of air that are slightly warmer, colder, wetter, or drier. (8) Every change in the air changes how the arms grow. (9) Because of this, the arms of one flake might be thin and feathery while the arms of another are short and flat. (10) That is why scientists say it is very unlikely that any two snowflakes are exactly alike.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
