  ('13b8369d-7590-5298-9bfb-5558fe9a1065', null, (select id from public.skills where slug = 'write-g7-sentence-structure'), null, 'medium',
   $q$Read the sentences: "The storm knocked out the power. The family lit candles. Their neighbor brought over a lantern." Which choice combines them into a compound-complex sentence?$q$, $q$[{"text":"During the storm, the family lit candles and got a lantern from their neighbor.","is_correct":false,"misconception_token":"simple-as-compound-complex"},{"text":"When the storm knocked out the power, the family lit candles and borrowed a lantern.","is_correct":false,"misconception_token":"complex-as-compound-complex"},{"text":"When the storm knocked out the power, the family lit candles, and their neighbor brought over a lantern.","is_correct":true},{"text":"The storm knocked out the power, so the family lit candles, and their neighbor brought over a lantern.","is_correct":false,"misconception_token":"compound-as-compound-complex"}]$q$::jsonb, $q$When the storm knocked out the power, the family lit candles, and their neighbor brought over a lantern.$q$, $q$A compound-complex sentence needs at least two independent clauses and at least one dependent clause, and the correct choice has the dependent clause "When the storm knocked out the power" plus two independent clauses joined by "and." The "so ... and" choice has three independent clauses but no dependent clause, so it is only compound.$q$, 'draft', null)
