  ('62839ad0-4776-52b2-ba0d-1f82e79849ae', null, (select id from public.skills where slug = 'write-g7-writing-with-evidence'), null, 'medium',
   $q$Which revision of sentence 7 best connects paragraph 2 to paragraph 1?$q$, $q$[{"text":"Even so, the ice did not really need to last for very long at all.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"For example, the ice also had to last all summer long after it was cut.","is_correct":false,"misconception_token":"wrong-transition"},{"text":"In conclusion, the ice also had to last all summer in the icehouse.","is_correct":false,"misconception_token":"premature-conclusion"},{"text":"Cutting the ice was only half the job, because the ice also had to last all summer.","is_correct":true}]$q$::jsonb, $q$Cutting the ice was only half the job, because the ice also had to last all summer.$q$, $q$"Cutting the ice was only half the job" reminds the reader of paragraph 1 (cutting) and introduces paragraph 2 (storing). "In conclusion" signals the end of the draft even though a whole paragraph of new evidence follows.$q$, 'draft', 'b983381f-3d6e-5881-90c7-f0189332f34d')
