values
  ('189b653a-247e-529d-8873-0bb75c2a9d60', null, (select id from public.skills where slug = 'write-g7-writing-with-evidence'), null, 'easy',
   $q$Sentence 2 is too vague. Which revision makes the claim clearer?$q$, $q$[{"text":"Haddad shows that the path opened to the public in the spring of 2021.","is_correct":false,"misconception_token":"fact-not-claim"},{"text":"Haddad shows that the new trail in Millbrook is very nice to look at.","is_correct":false,"misconception_token":"vague-claim"},{"text":"Haddad shows that the trail made Millbrook safer, healthier, and better for local shops.","is_correct":true},{"text":"Haddad shows that Millbrook should bring back trains on the old line.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Haddad shows that the trail made Millbrook safer, healthier, and better for local shops.$q$, $q$Paragraph 2 gives evidence about safe bike routes, active older residents, and a busier bakery, so the claim naming safety, health, and shops matches it. The opening date is a single fact, not a point the evidence proves.$q$, 'draft', '50dc02b2-2fe4-545a-9de0-3cc18dbbe6be')
