  ('c152f3d7-4439-559c-a441-ff482c179cab', null, (select id from public.skills where slug = 'write-g8-grammar-usage'), null, 'easy',
   $q$Which sentence uses the conditional mood?$q$, $q$[{"text":"Does Amara enjoy the robotics club?","is_correct":false,"misconception_token":"interrogative-read-as-conditional"},{"text":"Join the robotics club, Amara.","is_correct":false,"misconception_token":"imperative-read-as-conditional"},{"text":"Amara would enjoy the robotics club.","is_correct":true},{"text":"Amara enjoys the robotics club.","is_correct":false,"misconception_token":"indicative-read-as-conditional"}]$q$::jsonb, $q$Amara would enjoy the robotics club.$q$, $q$The conditional mood uses "would" (or "could" or "might") to show what would happen under certain conditions, so "Amara would enjoy the robotics club" is conditional. "Amara enjoys the robotics club" simply states a fact, so it is indicative.$q$, 'draft', null)
