values
  ('98ba488d-1d94-5a99-8473-2511b6f223c7', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'easy',
   $q$Sentence 14 tells about Mrs. Delgado's opinion instead of showing it. Which revision uses dialogue and detail to show it?$q$, $q$[{"text":"Mrs. Delgado knelt beside the bean row. \"I haven't grown anything since I was a girl,\" she said softly.","is_correct":true},{"text":"\"Nice,\" someone said, though it was hard to tell who.","is_correct":false,"misconception_token":"unclear-speaker"},{"text":"Mrs. Delgado said the garden was nice, and it really was nice.","is_correct":false,"misconception_token":"adds-no-detail"},{"text":"Mrs. Delgado said that she thought the garden was really very nice.","is_correct":false,"misconception_token":"still-telling"}]$q$::jsonb, $q$Mrs. Delgado knelt beside the bean row. "I haven't grown anything since I was a girl," she said softly.$q$, $q$The correct choice shows Mrs. Delgado's action and her own words, which reveal what the garden means to her. The choice "Mrs. Delgado said that she thought the garden was really very nice" still reports her opinion without dialogue or detail.$q$, 'draft', '356ed476-6dec-50d7-999d-eefe687ba364')
