  ('9a98080a-a132-548d-b440-faf52c05093e', null, (select id from public.skills where slug = 'write-g8-narrative-writing'), null, 'easy',
   $q$Which revision of sentence 3 best uses sensory details to describe the setting?$q$, $q$[{"text":"The attic was hot and dusty, and it was also very hot.","is_correct":false,"misconception_token":"repetitive-detail"},{"text":"The attic was an attic at the top of our house.","is_correct":false,"misconception_token":"circular-description"},{"text":"Attics are often used by families for storing old things.","is_correct":false,"misconception_token":"general-fact-not-description"},{"text":"The attic air was thick and hot, and each step sent dust swirling through a beam of sunlight.","is_correct":true}]$q$::jsonb, $q$The attic air was thick and hot, and each step sent dust swirling through a beam of sunlight.$q$, $q$The correct choice appeals to touch and sight with thick, hot air and swirling dust. The choice about storing old things is a general fact and does not describe this attic.$q$, 'draft', 'b8b6da68-3cce-5c31-a362-e882a6d91854')
